<script setup lang="ts">
import {reactive,ref,watch,computed,onMounted} from 'vue'
import {FolderOpen,KeyRound,Check,ShieldCheck,Monitor,Save} from '@lucide/vue'
import type {Config,GeminiConnection} from '../types'
const props=defineProps<{config:Config;saveConfig:(value:Config)=>Promise<unknown>;saveKey:(value:string)=>Promise<unknown>;pick:(kind:string)=>Promise<string|null>;getConnection?:()=>Promise<GeminiConnection>;testConnection?:()=>Promise<GeminiConnection>}>()
const values=reactive({...props.config}),key=ref(''),busy=ref(false),message=ref(''),failure=ref('')
const connection=ref<GeminiConnection|null>(null),validating=ref(false)
const statusLabel=computed(()=>validating.value?'Validando…':connection.value?.status==='valid'?'Conexão validada':connection.value?.status==='invalid'?'Chave sem acesso':connection.value?.status==='unavailable'?'Conexão indisponível':props.config.gemini_key_configured?'Chave salva · não testada':'Chave não configurada')
const models=computed(()=>connection.value?.models||[])
const listed=computed(()=>models.value.some(m=>m.id===values.gemini_model))
const missingModel=computed(()=>connection.value?.status==='valid'&&!listed.value)
watch(()=>props.config,(value,old)=>{for(const field of Object.keys(value) as (keyof Config)[]){if(value[field]!==old[field])Object.assign(values,{[field]:value[field]})}},{deep:true})
onMounted(async()=>{if(props.getConnection)try{connection.value=await props.getConnection()}catch(e){failure.value=(e as Error).message}})
async function execute(fn:()=>Promise<unknown>,success:string){busy.value=true;failure.value='';message.value='';try{await fn();message.value=success}catch(e){failure.value=(e as Error).message}finally{busy.value=false}}
async function saveKey(){validating.value=true;await execute(async()=>{const result=await props.saveKey(key.value);if(result)connection.value=result as GeminiConnection;key.value=''},'Conexão validada. Chave armazenada no Windows.');validating.value=false}
async function testConnection(){if(!props.testConnection)return;validating.value=true;await execute(async()=>{connection.value=await props.testConnection!()},'');validating.value=false}
async function saveSettings(){if(!missingModel.value)await execute(()=>props.saveConfig({...values}),'Configurações salvas.')}
async function pick(kind:string,field:'asr_model_path'|'ffmpeg'|'ffprobe'){await execute(async()=>{const result=await props.pick(kind);if(result)values[field]=result},'')}
</script>
<template>
  <header class="page-heading"><div><p class="breadcrumb">Preferências do aplicativo</p><h1>Configurações</h1><p>Seu processamento local. Seu modelo de análise.</p></div></header>
  <div class="settings-grid">
    <form class="settings-main" @submit.prevent="saveSettings">
      <section class="setting-section"><h2><Monitor :size="19"/>Processamento local</h2><p>Transcrição e renderização usam a CPU. Escolha os recursos já instalados.</p><label class="field">Pasta do modelo Whisper<span class="input-action"><input v-model="values.asr_model_path" required/><button type="button" class="icon-button" title="Escolher pasta do modelo" @click="pick('model','asr_model_path')"><FolderOpen :size="18"/></button></span><small>Modelo multilíngue com suporte ao português; arquivos ficam locais.</small></label><div class="field-pair"><label class="field">FFmpeg<span class="input-action"><input v-model="values.ffmpeg" required/><button type="button" class="icon-button" title="Localizar FFmpeg" @click="pick('ffmpeg','ffmpeg')"><FolderOpen :size="17"/></button></span></label><label class="field">ffprobe<span class="input-action"><input v-model="values.ffprobe" required/><button type="button" class="icon-button" title="Localizar ffprobe" @click="pick('ffprobe','ffprobe')"><FolderOpen :size="17"/></button></span></label></div></section>
      <section class="setting-section"><h2>Seleção de trechos</h2><p>A análise com Gemini é opcional e só começa quando você autorizar no projeto.</p><label class="field">Modelo Gemini<select v-model="values.gemini_model" data-field="gemini-model" required :disabled="busy||!models.length"><option v-if="!listed" :value="values.gemini_model" disabled>{{values.gemini_model}} — {{missingModel?'não aparece no catálogo':'modelo salvo'}}</option><option v-for="model in models" :key="model.id" :value="model.id">{{model.display_name}} · {{model.id}}</option></select><small v-if="missingModel">O modelo salvo não aparece no catálogo. Escolha outro modelo explicitamente.</small><small v-else>{{models.length?models.length+' modelos disponíveis.':'Teste a conexão para carregar os modelos disponíveis.'}}</small></label><div class="field-pair"><label class="field">Limite de tentativas<input type="number" v-model.number="values.max_calls" min="1" max="100" required/><small>Inclui retries e reparação de JSON.</small></label><label class="field">Janela de análise (segundos)<input type="number" v-model.number="values.window_seconds" min="60" max="1800" required/></label></div><label class="field">Máximo de caracteres por janela<input type="number" v-model.number="values.max_text_chars" min="1000" max="300000" required/></label></section>
      <div class="setting-save"><button class="button primary" data-action="save-config" :disabled="busy||missingModel"><Save :size="16"/>Salvar configurações</button></div>
    </form>
    <aside class="settings-aside"><section class="credential-panel"><div class="section-icon"><KeyRound :size="22"/></div><h2>Chave Gemini</h2><span class="status-pill" :data-status="validating?'running':connection?.status==='valid'?'completed':'pending'"><i></i>{{statusLabel}}</span><p v-if="connection?.status==='invalid'||connection?.status==='unavailable'" role="alert">{{connection.message}}</p><p>Armazenada no Gerenciador de Credenciais do Windows. O aplicativo não exibe a chave salva.</p><label class="field">{{config.gemini_key_configured?'Substituir chave':'Adicionar chave'}}<input type="password" v-model="key" autocomplete="new-password" placeholder="Cole sua chave de API"/></label><button type="button" class="button secondary full" data-action="save-key" :disabled="busy||!key.trim()" @click="saveKey"><KeyRound :size="16"/>{{validating?'Validando…':'Salvar e validar'}}</button><button type="button" class="button secondary full" data-action="test-gemini" :disabled="busy||!config.gemini_key_configured" @click="testConnection">{{validating?'Validando…':'Testar conexão / Atualizar modelos'}}</button><p v-if="connection?.checked_at">Último teste: {{new Date(connection.checked_at).toLocaleString('pt-BR')}}</p><p>O teste consulta apenas o catálogo. Não gera conteúdo nem verifica a cota de geração.</p></section><section class="local-info"><ShieldCheck :size="23"/><h3>O vídeo fica aqui</h3><p>O provedor recebe apenas a transcrição em texto. Vídeo, áudio e frames não são enviados.</p><div class="resource-line"><Check :size="15"/>{{config.asr_available?'Modelo local disponível':'Modelo local não encontrado'}}</div><div class="resource-line"><Check :size="15"/>{{config.tools_available?'Ferramentas de vídeo disponíveis':'Localize FFmpeg e ffprobe'}}</div></section></aside>
  </div><p v-if="message" class="notice success" role="status">{{message}}</p><p v-if="failure" class="notice error" role="alert">{{failure}}</p>
</template>
